#!/usr/bin/env python3
"""
gen-readme.py — Generate the root README.md from registry.json.

Reads registry.json (single source of truth) and emits README.md at the repo
root with:
  - a one-paragraph "what the accelerator is" intro
  - the ai-baseline dependency note
  - a "Start here" workflow map
  - a generated capability table (plugin | kind | one-line purpose | primary command | enricher prefix)
  - the maintainer and homepage from ${KIT_HOME}/kit.config.yaml

It also writes kit.author_name / kit.author_email into the identity lines of the
plugin docs (maintainer lines, OpenAPI contact, converter author, report footer)
and switches the release check of every skills/version-self-check.md on or off
with kit.homepage (empty = off). See tools/kit_identity.py. A bad config or a
doc that lost its identity line stops the run before anything is written.

README generation is IDEMPOTENT: running this script twice produces no git diff.

Usage:
    python3 tools/gen-readme.py
"""

import importlib.util
import json
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent


def load_kit_identity():
    """tools/kit_identity.py, loaded by path (works without sys.path)."""
    path = Path(__file__).resolve().parent / "kit_identity.py"
    spec = importlib.util.spec_from_file_location("kit_identity", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

# --------------------------------------------------------------------------- #
# Plugin one-line purposes — derived from plugin.json descriptions (truncated  #
# to 72 chars for table fit).  gen-readme reads these dynamically from the    #
# plugin.json files; they are NOT hand-maintained here.                       #
# --------------------------------------------------------------------------- #

# Width constants for the table
COL_PLUGIN  = 34
COL_KIND    = 11
COL_PURPOSE = 72
COL_PRIMARY = 26
COL_PREFIX  = 7


def _trunc(s: str, n: int) -> str:
    """Truncate string to n chars, appending … if truncated."""
    s = s.strip()
    if len(s) <= n:
        return s
    return s[: n - 1] + "…"


def load_registry() -> list[dict]:
    reg_path = REPO_ROOT / "registry.json"
    if not reg_path.exists():
        print("ERROR: registry.json not found. Run gen-registry.py first.", file=sys.stderr)
        sys.exit(1)
    return json.loads(reg_path.read_text(encoding="utf-8"))


def load_plugin_description(name: str) -> str:
    """Load short description from plugin.json, or fall back to empty string."""
    pjson = REPO_ROOT / name / ".claude-plugin" / "plugin.json"
    if not pjson.exists():
        return ""
    data = json.loads(pjson.read_text(encoding="utf-8"))
    return data.get("description", "")


def build_readme(entries: list[dict], identity: dict) -> str:
    # ------------------------------------------------------------------ #
    # Header                                                               #
    # ------------------------------------------------------------------ #
    lines: list[str] = []
    lines.append("<!-- AUTO-GENERATED by tools/gen-readme.py — do not edit by hand -->")
    lines.append("")
    lines.append("# Accelerator")
    lines.append("")

    # ------------------------------------------------------------------ #
    # What is the accelerator                                              #
    # ------------------------------------------------------------------ #
    lines.append(
        "The **Accelerator** is a Claude Code plugin suite that turns a bare project into "
        f"a governed, production-ready codebase. It ships {len(entries)} composable plugins — covering "
        "greenfield initialisation, code review, API design, observability, compliance, "
        "release management, and more — all wired to a shared `ai-baseline` substrate that "
        "provides an audit trail, PII scrub, and cost gate on every agent call."
    )
    lines.append("")

    # ------------------------------------------------------------------ #
    # ai-baseline dependency note                                          #
    # ------------------------------------------------------------------ #
    lines.append("## ai-baseline dependency")
    lines.append("")
    lines.append(
        "Every `runtime` plugin in this suite declares `requires: [\"ai-baseline\"]`. "
        "Install `ai-baseline` first; it injects the mandatory `baseline-enforcer` skill "
        "into every agent, ensuring audit logging, PII scrubbing, and Opus cost-gating "
        "are active before any output is emitted."
    )
    lines.append("")

    # ------------------------------------------------------------------ #
    # Start here workflow map                                              #
    # ------------------------------------------------------------------ #
    lines.append("## Start here")
    lines.append("")
    lines.append("| Goal | Plugin | Entry command |")
    lines.append("|------|--------|---------------|")
    lines.append("| Start a new project from scratch | greenfield-project-initializer | `/greenfield` |")
    lines.append("| Understand an existing codebase | onboarding-guide | `/onboarding` |")
    lines.append("| Ongoing development companion | dev-companion | `/review`, `/spec`, `/adr` |")
    lines.append("| Spec written — inject production requirements | ai-baseline | `/enrich <spec>` |")
    lines.append("| Prepare for release | release-manager | `/release` |")
    lines.append("| Manage a multi-repo workspace | workspace-companion | `/workspace-init` |")
    lines.append("| Modernize a legacy codebase | legacy-modernizer | `/modernize` |")
    lines.append("")

    # ------------------------------------------------------------------ #
    # Capability table                                                     #
    # ------------------------------------------------------------------ #
    lines.append("## Capability catalog")
    lines.append("")

    # Build table rows
    # Header row
    header_plugin  = "Plugin".ljust(COL_PLUGIN)
    header_kind    = "Kind".ljust(COL_KIND)
    header_purpose = "Purpose".ljust(COL_PURPOSE)
    header_primary = "Primary command".ljust(COL_PRIMARY)
    header_prefix  = "Prefix".ljust(COL_PREFIX)

    lines.append(
        f"| {header_plugin} | {header_kind} | {header_purpose} | {header_primary} | {header_prefix} |"
    )
    lines.append(
        f"| {'-' * COL_PLUGIN} | {'-' * COL_KIND} | {'-' * COL_PURPOSE} | {'-' * COL_PRIMARY} | {'-' * COL_PREFIX} |"
    )

    for entry in entries:
        name     = entry["name"]
        kind     = entry.get("kind", "runtime")
        commands = entry.get("commands", [])
        prefix   = entry.get("enricher_prefix") or "—"
        desc     = load_plugin_description(name)

        # Primary command = first command in the sorted list (strip .md)
        if commands:
            primary_cmd = "/" + commands[0].replace(".md", "")
        else:
            primary_cmd = "—"

        col_name    = _trunc(name, COL_PLUGIN).ljust(COL_PLUGIN)
        col_kind    = _trunc(kind, COL_KIND).ljust(COL_KIND)
        col_purpose = _trunc(desc, COL_PURPOSE).ljust(COL_PURPOSE)
        col_primary = _trunc(primary_cmd, COL_PRIMARY).ljust(COL_PRIMARY)
        col_prefix  = _trunc(prefix, COL_PREFIX).ljust(COL_PREFIX)

        lines.append(
            f"| {col_name} | {col_kind} | {col_purpose} | {col_primary} | {col_prefix} |"
        )

    lines.append("")

    # ------------------------------------------------------------------ #
    # Maintainer (kit.config.yaml)                                         #
    # ------------------------------------------------------------------ #
    lines.append("## Maintainer")
    lines.append("")
    lines.append(f"{identity['author_name']} ({identity['author_email']})")
    if identity["homepage"]:
        lines.append("")
        lines.append(f"Homepage: {identity['homepage']}")
    lines.append("")

    # ------------------------------------------------------------------ #
    # Footer                                                               #
    # ------------------------------------------------------------------ #
    lines.append("---")
    lines.append("")
    lines.append(
        "_This file is auto-generated by `tools/gen-readme.py` from `registry.json` "
        "and each plugin's `plugin.json`. Re-run `python3 tools/gen-readme.py` after "
        "adding or modifying a plugin._"
    )
    lines.append("")

    return "\n".join(lines)


def main() -> int:
    kit = load_kit_identity()
    try:
        identity = kit.load_identity(REPO_ROOT)
        docs = kit.identity_doc_updates(REPO_ROOT, identity)
    except (kit.ConfigError, kit.DocError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        print("ABORT: nothing written.", file=sys.stderr)
        return 2

    entries = load_registry()
    readme  = build_readme(entries, identity)

    out_path = REPO_ROOT / "README.md"
    out_path.write_text(readme, encoding="utf-8")
    print(f"README.md written ({len(entries)} plugins listed).")
    kit.write_updates(docs)
    print(f"docs: identity lines and release check from kit config ({len(docs)} file(s) updated)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
